//! FULL-CELL byte-identity against the reference crate: given identical
//! seeded randomness, this crate must produce byte-identical cells, payload
//! keys, per-hop secrets, per-hop post-processing states, and SURB replies.
//!
//! cells.txt is generated by running `tools/dump_cells.rs` (shipped in this
//! pack) against the std-only reference crate (`pq_sphinx_pack`):
//!
//! ```bash
//! cargo run --example dump_cells --release > cells.txt
//! ```
//!
//! Seed schedule (must match tools/dump_cells.rs):
//! - `cell_v{v}` scenarios: keygen seed 1000+v (v = 2..5)
//! - `cell_loop` (path A,B,A): keygen seed 77
//! - `surb_v{v}` scenarios: keygen seed 2000+v (v = 2..4)
//! - build randomness: DetRng(keygen_seed ^ 0x5EED)
//! - SURB reply randomness: DetRng(keygen_seed ^ 0x1234)
//!
//! The reference crate is itself cross-verified against Python (kyber-py,
//! cryptography, blake3, hashlib), so byte-equality here transitively pins
//! this crate's protocol serialization to the reviewed oracle.

use avpn_mix_lane::sphinx::{
    build_cell, build_surb, mix_keypair, open_payload, open_surb_reply, process_cell,
    surb_reply_cell, DetRng, MixKeys,
};
use std::collections::HashMap;
use std::fs;

type VecMap = HashMap<(String, String), Vec<u8>>;

fn cells() -> VecMap {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/cells.txt");
    let text = fs::read_to_string(path).expect("cells.txt next to Cargo.toml");
    let mut map = HashMap::new();
    for line in text.lines() {
        let parts: Vec<&str> = line.split('|').collect();
        assert_eq!(parts.len(), 3, "bad line: {line}");
        let bytes: Vec<u8> = (0..parts[2].len() / 2)
            .map(|i| u8::from_str_radix(&parts[2][2 * i..2 * i + 2], 16).unwrap())
            .collect();
        map.insert((parts[0].to_string(), parts[1].to_string()), bytes);
    }
    map
}

fn get(m: &VecMap, name: &str, field: &str) -> Vec<u8> {
    m.get(&(name.to_string(), field.to_string()))
        .unwrap_or_else(|| panic!("missing {name}|{field}"))
        .clone()
}

fn arr32(b: &[u8]) -> [u8; 32] {
    b.try_into().unwrap()
}

/// Rebuild the mixes exactly as dump_cells.rs did, from the recorded seeds
/// (d, z, x25519_sk per mix), asserting the derived keys match the recorded
/// ones along the way.
fn rebuild_mixes(
    v: &VecMap,
    name: &str,
    v_hops: usize,
    _keygen_seed: u64,
) -> Vec<(MixKeys, avpn_mix_lane::sphinx::MixSecret)> {
    let mut mixes = Vec::new();
    for i in 0..v_hops {
        let id = get(v, name, &format!("k{i}_id"));
        let d = arr32(&get(v, name, &format!("k{i}_d")));
        let z = arr32(&get(v, name, &format!("k{i}_z")));
        let xsk = arr32(&get(v, name, &format!("k{i}_xsk")));
        let (k, s) = mix_keypair(&d, &z, xsk, id[..].try_into().unwrap());
        // Keygen determinism: audited crates reproduce the reference keys.
        assert_eq!(
            k.mlkem_ek,
            get(v, name, &format!("k{i}_ek")),
            "{name} k{i}_ek"
        );
        assert_eq!(
            k.x25519_pk.to_vec(),
            get(v, name, &format!("k{i}_xpk")),
            "{name} k{i}_xpk"
        );
        assert_eq!(
            s.mlkem_dk,
            get(v, name, &format!("k{i}_dk")),
            "{name} k{i}_dk"
        );
        assert_eq!(
            s.x25519_sk.to_vec(),
            get(v, name, &format!("k{i}_xsk_out")),
            "{name} k{i}_xsk_out"
        );
        mixes.push((k, s));
    }
    mixes
}

fn path_of(mixes: &[(MixKeys, avpn_mix_lane::sphinx::MixSecret)]) -> Vec<MixKeys> {
    mixes.iter().map(|(k, _)| k.clone()).collect()
}

#[test]
fn byte_identity_forward_cells_v2_to_v5() {
    let v = cells();
    for v_hops in 2..=5usize {
        let name = format!("cell_v{v_hops}");
        let seed = 1000 + v_hops as u64;
        let mixes = rebuild_mixes(&v, &name, v_hops, seed);
        let path = path_of(&mixes);

        let mailbox: [u8; 16] = get(&v, &name, "mailbox")[..].try_into().unwrap();
        let msg = get(&v, &name, "msg");
        let built = build_cell(&path, &mailbox, &msg, &mut DetRng(seed ^ 0x5EED)).unwrap();

        assert_eq!(
            built.cell,
            get(&v, &name, "cell"),
            "{name}: full cell bytes"
        );
        assert_eq!(
            built.payload_key.to_vec(),
            get(&v, &name, "pkey"),
            "{name}: payload key"
        );
        for (i, s) in built.hop_secrets.iter().enumerate() {
            assert_eq!(
                s.to_vec(),
                get(&v, &name, &format!("hsec{}", i + 1)),
                "{name}: hop secret {}",
                i + 1
            );
        }

        // Per-hop post-processing states must match byte for byte.
        let mut cell = built.cell.clone();
        for (i, (_, sec)) in mixes.iter().enumerate() {
            let _ = process_cell(&mut cell, sec).unwrap();
            assert_eq!(
                cell,
                get(&v, &name, &format!("post{}", i + 1)),
                "{name}: post{}",
                i + 1
            );
        }
        assert_eq!(
            open_payload(&cell, &built.payload_key).unwrap(),
            msg,
            "{name}: opened"
        );
    }
}

#[test]
fn byte_identity_repeated_mix_path() {
    // cell_loop: path (A, B, A) — the repeated mix owns slots 1 and 3.
    let v = cells();
    let name = "cell_loop";
    let seed = 77u64;
    let mixes = rebuild_mixes(&v, name, 3, seed);
    let path = path_of(&mixes);

    let mailbox: [u8; 16] = get(&v, name, "mailbox")[..].try_into().unwrap();
    let msg = get(&v, name, "msg");
    let built = build_cell(&path, &mailbox, &msg, &mut DetRng(seed ^ 0x5EED)).unwrap();
    assert_eq!(built.cell, get(&v, name, "cell"), "{name}: full cell bytes");

    let mut cell = built.cell.clone();
    for (i, (_, sec)) in mixes.iter().enumerate() {
        let _ = process_cell(&mut cell, sec).unwrap();
        assert_eq!(
            cell,
            get(&v, name, &format!("post{}", i + 1)),
            "{name}: post{}",
            i + 1
        );
    }
    assert_eq!(open_payload(&cell, &built.payload_key).unwrap(), msg);
}

#[test]
fn byte_identity_surbs_v2_to_v4() {
    let v = cells();
    for v_hops in 2..=4usize {
        let name = format!("surb_v{v_hops}");
        let seed = 2000 + v_hops as u64;
        let mixes = rebuild_mixes(&v, &name, v_hops, seed);
        let path = path_of(&mixes);

        let mailbox: [u8; 16] = get(&v, &name, "mailbox")[..].try_into().unwrap();
        let surb = build_surb(&path, &mailbox, &mut DetRng(seed ^ 0x5EED)).unwrap();
        assert_eq!(surb.bytes, get(&v, &name, "surb"), "{name}: surb bytes");
        assert_eq!(
            surb.reply_secret.to_vec(),
            get(&v, &name, "reply_secret"),
            "{name}: reply secret"
        );

        let reply_msg = get(&v, &name, "reply_msg");
        let cell = surb_reply_cell(&surb.bytes, &reply_msg, &mut DetRng(seed ^ 0x1234)).unwrap();
        assert_eq!(cell, get(&v, &name, "reply_cell"), "{name}: reply cell");

        let mut cell = cell;
        for (i, (_, sec)) in mixes.iter().enumerate() {
            process_cell(&mut cell, sec).unwrap();
            assert_eq!(
                cell,
                get(&v, &name, &format!("post{}", i + 1)),
                "{name}: post{}",
                i + 1
            );
        }
        assert_eq!(
            open_surb_reply(&surb.reply_secret, &surb.path_secrets, &cell).unwrap(),
            reply_msg,
            "{name}: opened"
        );
    }
}
